package io.finstream.state;
import static org.assertj.core.api.Assertions.assertThat; import io.finstream.domain.MarketEvent; import java.math.BigDecimal; import java.time.Instant; import org.junit.jupiter.api.Test;
class InMemoryRollingMarketStateStoreTest { private MarketEvent e(Instant t,String p,String q){return new MarketEvent("TEST","BTCUSDT",MarketEvent.EventType.TRADE,t,t,new BigDecimal(p),new BigDecimal(q));} @Test void calculatesWindowsAndEvictsOldTicks(){var s=new InMemoryRollingMarketStateStore(); Instant t=Instant.parse("2024-01-01T00:00:00Z"); s.update(e(t.minusSeconds(1900),"50","9")); s.update(e(t.minusSeconds(240),"100","4")); s.update(e(t.minusSeconds(30),"105","2")); var state=s.update(e(t,"110","3")); assertThat(state.return5m()).isEqualTo(10); assertThat(state.volume1m()).isEqualTo(5); assertThat(state.volume5m()).isEqualTo(9); assertThat(state.high5m()).isEqualByComparingTo("110"); assertThat(state.low5m()).isEqualByComparingTo("100"); assertThat(state.volumeRatio()).isEqualTo(5);}}
